skills.card:
checkTitleCase — Check a title against title-case rules and show which words were wrong.
  needs: text: string
  e.g. "put this in title case" → {"text":"the lord of the rings"}

markdownToHtml — Convert Markdown into HTML.
  needs: markdown: string
  e.g. "convert this markdown to html" → {"markdown":"# Title\n\nSome **bold** text."}

paragraphStats — Break a document into paragraphs and report the word and sentence count of each.
  needs: text: string
  e.g. "break this document into paragraph stats" → {"text":"First paragraph here. It has two sentences.\n\nSecond one is shorter."}

singularize — Cut a plural English word back to one of the thing.
  needs: word: string
  e.g. "what is the singular of children" → {"word":"children"}

compareSemver — Say which of two version numbers is the newer.
  needs: a: string, b: string
  e.g. "is 2.11.5 newer than 2.9.0" → {"a":"2.11.5","b":"2.9.0"}

cronToText — Explain what a cron schedule expression means in plain English.
  needs: expression: string
  e.g. "what does this cron expression mean" → {"expression":"0 9 * * 1-5"}

escapeRegex — Escape special characters so text matches literally inside a regex pattern.
  needs: text: string
  e.g. "escape this for a regex: a.b" → {"text":"a.b"}

httpStatusLookup — Look up what an HTTP status code means.
  needs: code: integer
  e.g. "what does http 404 mean" → {"code":404}

jwtDecode — Decode the header and claims inside a JSON Web Token.
  needs: token: string
  e.g. "decode this jwt" → {"token":"eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.eyJzdWIiOiIxMjM0NTY3ODkwIiwibmFtZSI6IkFuYSIsImlhdCI6MTUxNjIzOTAyMn0.c2lnbmF0dXJl"}

mimeTypeLookup — Look up the MIME type for a file extension, or which extensions use a MIME type.
  needs: query: string
  e.g. "what mime type is a png" → {"query":"png"}

parseSemver — Split one version number into major, minor, patch and pre-release.
  needs: version: string
  e.g. "break down version 2.11.5" → {"version":"2.11.5"}

unicodeLookup — Look up a character by symbol, code point or name, with its encodings.
  needs: query: string
  e.g. "look up the character A" → {"query":"A"}

habitCompletionRate — Work out how many days you kept a habit, as a percentage of the days in the period.
  needs: dates: array, from: string, to: string
  e.g. "how often did I keep this habit" → {"dates":["2026-08-01","2026-08-02","2026-08-03"],"from":"2026-08-01","to":"2026-08-10"}

prioritizeTasks — Rank tasks by importance, urgency and how much effort they take.
  needs: tasks: array
  e.g. "prioritise these tasks" → {"tasks":[{"task":"file taxes","importance":5,"urgency":5,"effort":3},{"task":"tidy desk","importance":1,"urgency":2,"effort":1},{"task":"write report","importance":4,"urgency":3,"effort":2},{"task":"reply to email","importance":2,"urgency":5,"effort":1}]}

